<script setup lang="ts">
import type { ScopedCredential } from '~~/shared/utils/vault-sources'
const props=defineProps<{entries:ScopedCredential[];busy:boolean}>()
const emit=defineEmits<{edit:[entry:ScopedCredential];renew:[entry:ScopedCredential,fieldId:string]}>()
const {rows,today,selected,monthTitle,cells,selectedRows,move,goToday,status,dateLabel,moneyLabel,group,currency,search,statusFilter,groups,currencyOptions,statusOptions,selectedMonth,selectedYear,monthOptions,monthTotals,selectedTotals,amountLabel}=useSubscriptionCalendar(props)
</script>
<template>
 <section class="subscription-calendar">
  <SubscriptionFilters v-model:group="group" v-model:currency="currency" v-model:search="search" v-model:status="statusFilter" :groups="groups" :currency-options="currencyOptions" :status-options="statusOptions" />
  <div class="subscription-calendar-heading"><div><h2>{{ monthTitle }}</h2><p>Сроки оплаты и плановые списания. Всего подписок: {{ rows.length }}</p></div><div class="calendar-controls"><USelect v-model="selectedMonth" :items="monthOptions" aria-label="Месяц календаря" /><UInput v-model.number="selectedYear" type="number" :min="1900" :max="9998" aria-label="Год календаря" class="calendar-year" /><UButton variant="outline" color="neutral" icon="i-lucide-chevron-left" aria-label="Предыдущий месяц" @click="move(-1)" /><UButton variant="outline" color="neutral" label="Сегодня" @click="goToday" /><UButton variant="outline" color="neutral" icon="i-lucide-chevron-right" aria-label="Следующий месяц" @click="move(1)" /></div></div>
  <div class="calendar-total"><span>Плановые списания за месяц</span><strong v-for="total in monthTotals" :key="total.currency">{{ amountLabel(total.amount,total.currency) }}</strong><span v-if="!monthTotals.length">Нет списаний</span></div>
  <p v-if="!rows.length" class="subscription-empty">Добавьте дополнительное поле типа «Подписка» в карточке сервиса — здесь появится дата окончания.</p>
  <div class="subscription-calendar-scroll"><div class="subscription-calendar-grid">
   <div v-for="day in ['Пн','Вт','Ср','Чт','Пт','Сб','Вс']" :key="day" class="calendar-weekday">{{ day }}</div>
   <button v-for="cell in cells" :key="cell.date" class="calendar-day" :class="{outside:cell.outside,selected:cell.date===selected,today:cell.date===today}" :aria-label="`${dateLabel(cell.date)}, подписок: ${cell.events.length}`" :aria-pressed="cell.date===selected" @click="selected=cell.date"><span>{{ cell.day }}</span><small v-for="event in cell.events.slice(0,3)" :key="event.key" :class="{'is-overdue':event.date<today}" :title="`${event.row.entry.title} · ${event.row.field.label}`">{{ event.row.entry.title }} · {{ event.charge?amountLabel(event.amount,event.currency):'Окончание' }}</small><small v-if="cell.events.length>3">Ещё {{ cell.events.length-3 }}</small><strong v-for="total in cell.totals" :key="total.currency" class="calendar-cell-total">{{ amountLabel(total.amount,total.currency) }}</strong></button>
  </div></div>
  <div class="subscription-day-details"><h3>{{ dateLabel(selected) }}</h3><div class="calendar-total" v-if="selectedTotals.length"><span>К списанию</span><strong v-for="total in selectedTotals" :key="total.currency">{{ amountLabel(total.amount,total.currency) }}</strong></div><p v-if="!selectedRows.length">На этот день нет окончаний подписок.</p><article v-for="event in selectedRows" :key="event.key"><div><button class="subscription-service" @click="emit('edit',event.row.entry)">{{ event.row.entry.title }} · {{ event.row.field.label }}</button><p>{{ (event.row.entry.vaultNames??[event.row.entry.vaultName]).join(' · ') }} · {{ moneyLabel(event.row.subscription) }}</p><p>{{ event.charge?'Плановое списание':'Оплачено до' }}: {{ dateLabel(event.date) }}{{ event.forecast?' · Прогноз продления':' · '+status(event.row.daysLeft) }}</p></div><div class="flex gap-2"><UButton size="sm" color="neutral" variant="outline" label="Изменить" @click="emit('edit',event.row.entry)" /><UButton v-if="!event.forecast" size="sm" variant="soft" :disabled="busy" label="Отметить оплату" @click="emit('renew',event.row.entry,event.row.field.id)" /></div></article></div>
  <p class="subscription-note">Будущие повторные списания — прогноз по текущей цене и периоду. Подписки без автопродления показывают только окончание и не входят в сумму списаний. Календарь не выполняет платежи. После оплаты отметьте следующий период. Даты указаны по московскому времени.</p>
 </section>
</template>
